bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
image=create-videobot:local-poll
docker image inspect "$image" >/dev/null 2>&1 || { echo STK04_IMAGE_MISSING; exit 61; }
docker inspect "$name" >/dev/null 2>&1 || { echo STK04_CONTAINER_ABSENT; exit 62; }
token="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_telegram_token"}}{{.Source}}{{end}}{{end}}' "$name")"
dbpass="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_db_password"}}{{.Source}}{{end}}{{end}}' "$name")"
test -f "$token" && test -f "$dbpass" || { echo STK04_MOUNTS_MISSING; exit 63; }
pg="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])postgres([-_]|$)' || true)"
test "$(printf '%s\n' "$pg" | sed '/^$/d' | wc -l)" -eq 1 || { echo STK04_PG_NOT_UNIQUE; exit 64; }
user="$(docker exec "$pg" sh -c 'printf %s "$POSTGRES_USER"')"
net="$(docker inspect -f '{{range $k,$v := .NetworkSettings.Networks}}{{println $k}}{{end}}' "$pg" | sed '/^$/d')"
test -n "$user" && test "$net" = deploy_default || { echo STK04_PG_OWNER_UNVERIFIED; exit 65; }
docker run --rm -i --network "$net" --pull never \
 --cap-drop ALL --security-opt no-new-privileges:true \
 -e NODE_ENV=production -e VIDEOBOT_RUN_MODE=telegram_poll \
 -e VIDEOBOT_PRIVATE_INGRESS_ONLY=true -e VIDEOBOT_SCHEMA_MIGRATE=YES \
 -e VIDEOBOT_TELEGRAM_TOKEN_FILE=/run/secrets/videobot_telegram_token \
 -e VIDEOBOT_DB_PASSWORD_FILE=/run/secrets/videobot_db_password \
 -e VIDEOBOT_DB_HOST=deploy-postgres-1 -e VIDEOBOT_DB_NAME=videobot \
 -e VIDEOBOT_DB_USER="$user" \
 --mount "type=bind,source=$token,target=/run/secrets/videobot_telegram_token,readonly" \
 --mount "type=bind,source=$dbpass,target=/run/secrets/videobot_db_password,readonly" \
 --entrypoint node "$image" --input-type=module <<'JS'
import {createCreatorPollingRuntime} from './src/runtime/creatorPollingMain.mjs';
try {
 const rt=await createCreatorPollingRuntime();
 await rt.close();
 console.log('STK04_DIAG_RUNTIME_CONSTRUCT=PASS');
} catch(e) {
 const code=String(e?.code??'');
 const msg=String(e?.message??'');
 if(code==='28P01')process.exitCode=80;
 else if(code==='3D000')process.exitCode=81;
 else if(code==='42501')process.exitCode=82;
 else if(code==='ECONNREFUSED')process.exitCode=83;
 else if(code==='ENOTFOUND'||code==='EAI_AGAIN')process.exitCode=84;
 else if(code==='ETIMEDOUT'||code==='UND_ERR_CONNECT_TIMEOUT')process.exitCode=85;
 else if(code==='ERR_MODULE_NOT_FOUND')process.exitCode=86;
 else if(code==='ENOENT'||code==='EACCES')process.exitCode=87;
 else if(/source module missing owned dependencies|verified GATE owner provider missing/i.test(msg))process.exitCode=88;
 else if(/CREATOR_POLL_EXISTING_WEBHOOK_MUST_NOT_BE_REPLACED/.test(msg))process.exitCode=89;
 else if(/CREATOR_POLL_SCHEMA_INCOMPLETE|VideoBot migration/.test(msg))process.exitCode=90;
 else if(/verified bot|identity|CREATOR_BOT|TELEGRAM|HTTP/i.test(msg))process.exitCode=91;
 else if(/relation .* does not exist|syntax error|already exists|duplicate|constraint/i.test(msg))process.exitCode=92;
 else if(/getMe|401|403|404|429/.test(msg))process.exitCode=93;
 else if(/CREATOR_POLL_/.test(msg))process.exitCode=94;
 else process.exitCode=95;
}
JS
